  'A CalDAV or CardDAV server: iCloud (caldav.icloud.com), Fastmail, Nextcloud, Synology, Radicale and the like.': 'कोई CalDAV या CardDAV सर्वर: iCloud (caldav.icloud.com), Fastmail, Nextcloud, Synology, Radicale और ऐसे ही अन्य।',
  'A JSON file of accounts — address, password, servers — from another client or from whoever runs your mail. Each is tried before it is kept; one already set up is left alone.': 'खातों की एक JSON फ़ाइल — पता, पासवर्ड, सर्वर — किसी अन्य क्लाइंट से या आपकी मेल चलाने वाले से। प्रत्येक खाते को रखने से पहले आज़माया जाता है; जो खाता पहले से सेट है, उसे छेड़ा नहीं जाता।',
  'A PDF with no pages is not a document. Add a page first.': 'बिना पृष्ठों वाला PDF दस्तावेज़ नहीं होता। पहले एक पृष्ठ जोड़ें।',
