  'Click a symbol to insert it at the caret. The dialog stays open for the next one.': 'किसी प्रतीक को कैरेट पर सम्मिलित करने के लिए उस पर क्लिक करें। अगले प्रतीक के लिए संवाद खुला रहता है।',
  'Click a text box first, then mark its words as a language.': 'पहले किसी टेक्स्ट बॉक्स पर क्लिक करें, फिर उसके शब्दों को किसी भाषा के रूप में चिह्नित करें।',
  'Click a text box first.': 'पहले किसी टेक्स्ट बॉक्स पर क्लिक करें।',
