  'Draw Table — draw a line down a cell to split it into two columns there, or across it to split it into two rows; Escape puts the pen down': 'तालिका आरेखित करें — किसी कक्ष को वहीं दो स्तंभों में विभाजित करने के लिए उसमें खड़ी रेखा खींचें, या दो पंक्तियों में विभाजित करने के लिए आड़ी रेखा; Escape दबाने पर पेन रख दिया जाता है',
  'Draw Text Box': 'टेक्स्ट बॉक्स आरेखित करें',
  'Draw Text Box — drag on the page to draw one': 'टेक्स्ट बॉक्स आरेखित करें — एक बनाने के लिए पृष्ठ पर खींचें',
  'Draw a border round each slide': 'प्रत्येक स्लाइड के चारों ओर किनारी बनाएँ',
  'Draw a line down or across a cell to split it there.': 'किसी कक्ष को वहीं विभाजित करने के लिए उसमें खड़ी या आड़ी रेखा खींचें।',
  'Draw the table at least a fifth of an inch wide.': 'तालिका को कम से कम इंच के पाँचवें भाग जितना चौड़ा बनाएँ।',
  'Draw with Touch': 'स्पर्श से आरेखित करें',
  'Draw with Touch — a finger draws with the pen in hand; off, only a pen or the mouse does': 'स्पर्श से आरेखित करें — चालू होने पर उंगली चुने गए पेन से आरेखित करती है; बंद होने पर केवल पेन या माउस से आरेखण होता है',
