  'E-mail messages': 'ई-मेल संदेश',
  'Each account keeps its own options, as in Outlook.': 'Outlook की तरह, प्रत्येक खाता अपने विकल्प अलग रखता है।',
  'Each category is written as Word\'s TOA field, its heading over it; All writes one for every category that has citations in it.': 'प्रत्येक श्रेणी Word के TOA फ़ील्ड के रूप में लिखी जाती है, उसके ऊपर उसका शीर्षक होता है; “सभी” हर उस श्रेणी के लिए एक फ़ील्ड लिखता है जिसमें उद्धरण हैं।',
  'Each cell its own paragraph': 'प्रत्येक कक्ष एक अलग अनुच्छेद',
  'Each is set up as Add account does: a provider in the built-in list straight away; for any other domain, its own records are looked up when you press Add (its DNS, autoconfig and autodiscover addresses), and nothing else is asked.': 'हर खाता वैसे ही सेट होता है जैसे खाता जोड़ें में: अंतर्निहित सूची वाला प्रदाता तुरंत; किसी और डोमेन के अपने रिकॉर्ड जोड़ें दबाने पर ही देखे जाते हैं (उसका DNS, autoconfig और autodiscover पते), और किसी और से कुछ नहीं पूछा जाता।',
  'Each line is a paragraph of its own. Ctrl+Enter puts the words in.': 'प्रत्येक पंक्ति एक अलग अनुच्छेद है। Ctrl+Enter से शब्द सम्मिलित हो जाते हैं।',
  'Each message is the merged letter itself. The account\'s signature is not added: what you wrote in the letter is what each person receives.': 'प्रत्येक संदेश स्वयं मर्ज किया गया पत्र है। खाते का हस्ताक्षर नहीं जोड़ा जाता: आपने पत्र में जो लिखा है, वही प्रत्येक व्यक्ति को मिलता है।',
  'Each numbered level shows its own number: keep %{level} in level {level}\'s number.': 'प्रत्येक क्रमांकित स्तर अपनी संख्या स्वयं दिखाता है: स्तर {level} की संख्या में %{level} बनाए रखें।',
  'Each page is written as a picture into a folder you choose: {count} in all. This document is not changed.': 'हर पृष्ठ आपके चुने फ़ोल्डर में चित्र के रूप में लिखा जाता है: कुल {count}। यह दस्तावेज़ नहीं बदलता।',
  'Each sender hears from this once while it stays on — a second message from the same person is not answered again until it is turned off and on. A mailing list, a no-reply address and a message that already says it is automatic are never answered.': 'जब तक यह चालू रहता है, प्रत्येक प्रेषक को इससे केवल एक बार उत्तर मिलता है — उसी व्यक्ति के दूसरे संदेश का उत्तर तब तक दोबारा नहीं दिया जाता, जब तक इसे बंद करके फिर से चालू न किया जाए। मेलिंग सूची, नो-रिप्लाई पते और ऐसे संदेश को, जो पहले से स्वयं को स्वचालित बताता हो, कभी उत्तर नहीं दिया जाता।',
  'Each slide then moves on by itself after the time it was on screen, and Use Timings is turned on.': 'इसके बाद प्रत्येक स्लाइड उतने समय के बाद अपने आप आगे बढ़ जाती है जितनी देर वह स्क्रीन पर रही थी, और “समय का उपयोग करें” चालू हो जाता है।',
  'Each ticked field gets a panel of buttons, one per item, that filters the pivot table.': 'प्रत्येक चयनित फ़ील्ड को बटनों का एक पैनल मिलता है, हर आइटम के लिए एक बटन, जो PivotTable को फ़िल्टर करता है।',
  'Each ticked field gets a panel of buttons, one per item, that filters the table.': 'प्रत्येक चयनित फ़ील्ड को बटनों का एक पैनल मिलता है, हर आइटम के लिए एक बटन, जो तालिका को फ़िल्टर करता है।',
