  'Effects': 'प्रभाव',
  'Effects reach shapes styled from the theme — PowerPoint\'s shape styles are.': 'प्रभाव उन आकृतियों पर लागू होते हैं जिनकी शैली थीम से ली गई है — PowerPoint की आकृति शैलियाँ ऐसी ही होती हैं।',
  'Effects reach shapes styled from the theme, as Excel\'s own shape styles are.': 'प्रभाव उन आकृतियों पर लागू होते हैं जिनकी शैली थीम से ली गई है, जैसे Excel की अपनी आकृति शैलियाँ।',
  'Effects — how shapes styled from the theme are filled, outlined and lifted; now {name}': 'प्रभाव — थीम से शैली लेने वाली आकृतियों का भरण, रूपरेखा और उभार कैसा हो; अभी {name}',
  'Effects — how theme-styled shapes are filled, outlined and lifted': 'प्रभाव — थीम-शैली वाली आकृतियों का भरण, रूपरेखा और उभार कैसा हो',
  'Effects — the fills, lines and shadows that shapes taking their look from the theme are drawn with; now {effects}': 'प्रभाव — वे भरण, रेखाएँ और छायाएँ जिनसे थीम से अपना रूप लेने वाली आकृतियाँ बनाई जाती हैं; अभी {effects}',
