  'Empty prints everything with anything in it.': 'खाली छोड़ने पर वह सब कुछ प्रिंट होता है जिसमें कुछ भी भरा है।',
  'Encrypt': 'एन्क्रिप्ट करें',
  'Encrypt Document': 'दस्तावेज़ एन्क्रिप्ट करें',
  'Encrypt the contents of this file. It will open only with the password.': 'इस फ़ाइल की सामग्री एन्क्रिप्ट करें। यह केवल पासवर्ड से ही खुलेगी।',
  'Encrypt with Password': 'पासवर्ड से एन्क्रिप्ट करें',
  'Encrypt: import your certificate first': 'एन्क्रिप्ट करें: पहले अपना प्रमाणपत्र आयात करें',
  'Encrypt: only the recipients, and you, can read it': 'एन्क्रिप्ट करें: इसे केवल प्राप्तकर्ता और आप पढ़ सकते हैं',
  'Encrypted ({cipher}), and opened with your certificate for {email}.': 'एन्क्रिप्टेड ({cipher}), और {email} के लिए आपके प्रमाणपत्र से खोला गया।',
  'Encrypted mail is not sent to Bcc recipients: every recipient\'s certificate is named inside the message, so the others would see who had a blind copy. Send it to them separately.': 'एन्क्रिप्टेड मेल Bcc प्राप्तकर्ताओं को नहीं भेजी जाती: हर प्राप्तकर्ता का प्रमाणपत्र संदेश के अंदर लिखा होता है, इसलिए बाकी लोग देख लेंगे कि गुप्त प्रति किसे मिली। उन्हें अलग से भेजें।',
  'Encrypted with a password. Save to protect the file on disk.': 'पासवर्ड से एन्क्रिप्ट किया गया। डिस्क पर फ़ाइल को सुरक्षित करने के लिए सहेजें।',
