  'Equation — Office Math on this slide, typed in Word\'s linear format with a live preview; double-click one to edit it': 'समीकरण — इस स्लाइड पर Office Math, जिसे Word के रैखिक स्वरूप में लाइव पूर्वावलोकन के साथ टाइप किया जाता है; संपादित करने के लिए किसी समीकरण पर डबल-क्लिक करें',
  'Equation — double-click to edit': 'समीकरण — संपादित करने के लिए डबल-क्लिक करें',
  'Equation — type one in Word\'s linear format, or build it from structures and symbols (Alt+=)': 'समीकरण — Word के रैखिक स्वरूप में टाइप करें, या संरचनाओं और प्रतीकों से बनाएँ (Alt+=)',
  'Equation — typed in its linear form (x^2+y^2=r^2), set as math over the selection; double-click one to change it': 'समीकरण — अपने रैखिक रूप में टाइप किया गया (x^2+y^2=r^2), चयन के स्थान पर गणित के रूप में सेट किया गया; बदलने के लिए किसी समीकरण पर डबल-क्लिक करें',
  'Equations go on slides — Close Master View first.': 'समीकरण स्लाइडों पर लगते हैं — पहले “मास्टर दृश्य बंद करें” चुनें।',
