  'One Page': 'एक पृष्ठ',
  'One account a line: the address, then its password, separated by a space, a tab, a comma, a semicolon, a colon or a bar. A first line naming the columns (email, password, name, IMAP server...) is read as a table, as a spreadsheet saves one. A line starting # is left out.': 'हर पंक्ति में एक खाता: पता, फिर उसका पासवर्ड, जो स्पेस, टैब, कॉमा, सेमीकोलन, कोलन या बार से अलग हों। अगर पहली पंक्ति कॉलमों के नाम दे (email, password, name, IMAP server...) तो बाकी को तालिका की तरह पढ़ा जाता है, जैसे स्प्रेडशीट सहेजती है। # से शुरू होने वाली पंक्ति छोड़ दी जाती है।',
  'One column': 'एक स्तंभ',
  'One flow on screen for a native caret; the print and PDF layout actually splits it into columns': 'मूल कैरेट के लिए स्क्रीन पर एक ही प्रवाह; प्रिंट और PDF लेआउट इसे वास्तव में स्तंभों में विभाजित करता है',
  'One line per line. A tab moves to the centre, a second to the right.': 'हर पंक्ति के लिए एक पंक्ति। पहला टैब केंद्र में ले जाता है, दूसरा दाईं ओर।',
  'One range or several, such as B2:D10 F2:F10.': 'एक या कई श्रेणियाँ, जैसे B2:D10 F2:F10।',
  'One region marked for Everyone.': { one: '{count} क्षेत्र “सभी” के लिए चिह्नित है।', other: '{count} क्षेत्र “सभी” के लिए चिह्नित हैं।' },
  'Only Word, Excel and PowerPoint documents embed.': 'केवल Word, Excel और PowerPoint दस्तावेज़ ही एम्बेड होते हैं।',
  'Only a document has a design to set as the default.': 'केवल दस्तावेज़ में ही ऐसा डिज़ाइन होता है जिसे डिफ़ॉल्ट के रूप में सेट किया जा सके।',
  'Only a scratch file made in this run is added to.': 'केवल इसी रन में बनी अस्थायी फ़ाइल में ही जोड़ा जाता है।',
  'Only a scratch file of this suite is taken as a recording.': 'केवल इस सुइट की अस्थायी फ़ाइल को ही रिकॉर्डिंग के रूप में लिया जाता है।',
