  'Only a shape or a text box has words to change.': 'केवल आकृति या टेक्स्ट बॉक्स में ही बदलने योग्य शब्द होते हैं।',
  'Only a shape or a text box has words to transform.': 'केवल आकृति या टेक्स्ट बॉक्स में ही रूपांतरित करने योग्य शब्द होते हैं।',
  'Only a text box has words to transform.': 'केवल टेक्स्ट बॉक्स में ही रूपांतरित करने योग्य शब्द होते हैं।',
  'Only an entrance, emphasis or exit this writes can be played by paragraph': 'अनुच्छेद के अनुसार केवल वही प्रवेश, ज़ोर या निकास प्रभाव चलाया जा सकता है जिसे यह लिखता है',
  'Only certain kinds of changes can be made to this document — Review → Restrict Editing.': 'इस दस्तावेज़ में केवल कुछ प्रकार के परिवर्तन ही किए जा सकते हैं — समीक्षा → संपादन प्रतिबंधित करें।',
