  'Select all': 'सभी का चयन करें',
  'Select all (Ctrl+A)': 'सभी का चयन करें (Ctrl+A)',
  'Select everything here': 'यहाँ की हर चीज़ का चयन करें',
  'Select from one cell to another in the same table, then merge.': 'एक ही तालिका में एक कक्ष से दूसरे कक्ष तक चयन करें, फिर मर्ज करें।',
  'Select one or more floating drawings first (Shift+click adds one).': 'पहले एक या अधिक फ़्लोटिंग आरेखण चुनें (Shift+क्लिक से एक और जुड़ता है)।',
  'Select parts of the document and choose users who are allowed to freely edit them.': 'दस्तावेज़ के भाग चुनें और वे उपयोगकर्ता चुनें जिन्हें उन्हें स्वतंत्र रूप से संपादित करने की अनुमति है।',
  'Select recipients first — Mailings → Select Recipients.': 'पहले प्राप्तकर्ता चुनें — मेलिंग्स → प्राप्तकर्ता चुनें।',
  'Select rows from row 1 to repeat them': 'दोहराने के लिए पंक्ति 1 से शुरू होने वाली पंक्तियाँ चुनें',
  'Select some text first, and it becomes the link.': 'पहले कुछ टेक्स्ट चुनें, वही लिंक बन जाएगा।',
  'Select some words first.': 'पहले कुछ शब्द चुनें।',
  'Select some words, then Insert → Quick Parts → Save Selection to Quick Part Gallery.': 'कुछ शब्द चुनें, फिर सम्मिलित करें → त्वरित भाग → चयन को त्वरित भाग गैलरी में सहेजें।',
  'Select the cells to fill as well as the first one': 'पहले कक्ष के साथ-साथ भरे जाने वाले कक्ष भी चुनें',
