  'Select the words to keep first.': 'पहले रखे जाने वाले शब्द चुनें।',
  'Select three or more drawings to distribute': 'वितरित करने के लिए तीन या अधिक आरेखण चुनें',
  'Select three or more drawings to distribute.': 'वितरित करने के लिए तीन या अधिक आरेखण चुनें।',
  'Select three or more objects to distribute': 'वितरित करने के लिए तीन या अधिक ऑब्जेक्ट चुनें',
  'Select three or more objects to distribute.': 'वितरित करने के लिए तीन या अधिक ऑब्जेक्ट चुनें।',
  'Select three or more shapes first.': 'पहले तीन या अधिक आकृतियाँ चुनें।',
