  'Show Changes — {count} slide different since this deck was last open here': { one: 'परिवर्तन दिखाएँ — यहाँ पिछली बार खुलने के बाद से इस प्रस्तुति की {count} स्लाइड अलग है', other: 'परिवर्तन दिखाएँ — यहाँ पिछली बार खुलने के बाद से इस प्रस्तुति की {count} स्लाइड अलग हैं' },
