  'Show Media Controls': 'मीडिया नियंत्रण दिखाएँ',
  'Show Media Controls — a video in the show gets its play bar once it has started': 'मीडिया नियंत्रण दिखाएँ — शो में कोई वीडियो शुरू होने के बाद उसे अपनी प्ले पट्टी मिलती है',
  'Show Notes': 'नोट्स दिखाएँ',
  'Show Training': 'प्रशिक्षण दिखाएँ',
  'Show announcements from office.rutba.io — once a day at most. It sends the version and the operating system, and no identifier of any kind, so what is counted at the other end is "a copy opened somewhere", never you. It is also the only way we know the suite is being used at all.': 'office.rutba.io से घोषणाएँ दिखाएँ — दिन में अधिकतम एक बार। यह संस्करण और ऑपरेटिंग सिस्टम भेजता है, और किसी भी प्रकार का कोई पहचानकर्ता नहीं, इसलिए दूसरी ओर जो गिना जाता है वह “कहीं खोली गई एक प्रति” होती है, आप कभी नहीं। हमें यह पता चलने का भी यही एकमात्र तरीका है कि सुइट का उपयोग हो भी रहा है।',
  'Show every formula instead of its result (Ctrl+`)': 'हर सूत्र को उसके परिणाम के बजाय दिखाएँ (Ctrl+`)',
  'Show formatting marks (¶)': 'स्वरूपण चिह्न दिखाएँ (¶)',
  'Show formulas': 'सूत्र दिखाएँ',
  'Show in folder': 'फ़ोल्डर में दिखाएँ',
  'Show options': 'शो विकल्प',
  'Show page numbers': 'पृष्ठ संख्याएँ दिखाएँ',
  'Show password': 'पासवर्ड दिखाएँ',
  'Show sign date in signature line': 'हस्ताक्षर रेखा में हस्ताक्षर का दिनांक दिखाएँ',
  'Show slides': 'स्लाइड दिखाएँ',
  'Show the bookmark\'s value here, after the field': 'बुकमार्क का मान यहाँ, फ़ील्ड के बाद दिखाएँ',
  'Show the gridlines on screen': 'स्क्रीन पर ग्रिडलाइन दिखाएँ',
