  'Signature Line — a line for someone to sign in Word, with their name, title and e-mail under it': 'हस्ताक्षर रेखा — किसी व्यक्ति के Word में हस्ताक्षर करने के लिए एक रेखा, जिसके नीचे उसका नाम, पद और ई-मेल हो',
