  'Signature: your signature, typed, drawn or from a picture, placed where you click; not a digital signature': 'हस्ताक्षर: आपके हस्ताक्षर, टाइप किए, बनाए या चित्र से, जहाँ क्लिक करें वहाँ रखे जाते हैं; डिजिटल हस्ताक्षर नहीं',
  'Signed by': 'हस्ताक्षरकर्ता',
  'Signed by {name} with a certificate that is not meant for mail.': '{name} ने ऐसे प्रमाणपत्र से हस्ताक्षर किए जो मेल के लिए नहीं है।',
  'Signed by {name}, and the message has not changed, but no authority this computer trusts vouches for the certificate.': '{name} द्वारा हस्ताक्षरित, और संदेश नहीं बदला, लेकिन इस कंप्यूटर का कोई विश्वसनीय प्राधिकरण इस प्रमाणपत्र की पुष्टि नहीं करता।',
  'Signed by {name}, and the message has not changed, but the certificate is out of date.': '{name} के हस्ताक्षर, और संदेश नहीं बदला, लेकिन प्रमाणपत्र की अवधि समाप्त हो चुकी है।',
  'Signed by {name}, but the message has changed since it was signed. Do not rely on what it says.': '{name} द्वारा हस्ताक्षरित, लेकिन हस्ताक्षर के बाद संदेश बदल गया है। इसकी बातों पर भरोसा न करें।',
  'Signed by {name}, but the message names no sender to compare the certificate with.': '{name} के हस्ताक्षर, लेकिन संदेश में कोई भेजने वाला नहीं लिखा जिससे प्रमाणपत्र की तुलना की जाए।',
  'Signed by {name}, who is not the sender: the certificate is for {email}, and the message says it is from {from}.': '{name} के हस्ताक्षर, जो भेजने वाले नहीं हैं: प्रमाणपत्र {email} का है, और संदेश कहता है कि यह {from} की ओर से है।',
  'Signed by {name}. The signature is valid and the message has not changed since it was signed.': '{name} द्वारा हस्ताक्षरित। हस्ताक्षर मान्य है और हस्ताक्षर के बाद से संदेश नहीं बदला है।',
  'Signed on': 'हस्ताक्षर की तारीख',
