  'This {noun} already needs a password to open. Type a new one to change it, or leave both boxes empty to remove it.': 'इस {noun} को खोलने के लिए पहले से ही पासवर्ड आवश्यक है। इसे बदलने के लिए नया पासवर्ड टाइप करें, या इसे हटाने के लिए दोनों बॉक्स खाली छोड़ दें।',
  'Those two requests, and the mail and calendar servers you set up yourself, are everything Rutba Office ever contacts. Your documents, your mail and what you do with them never leave this computer.': 'वे दो अनुरोध, और वे मेल और कैलेंडर सर्वर जिन्हें आपने स्वयं सेट किया है, बस यही सब हैं जिनसे Rutba Office कभी संपर्क करता है। आपके दस्तावेज़, आपकी मेल और आप उनके साथ जो करते हैं, वह सब कभी इस कंप्यूटर से बाहर नहीं जाता।',
