  'Type into the form\'s fields, tick its boxes and choose from its lists. A signature placed here is a picture of your signature, not a digital signature: it does not prove who signed, or that the PDF has not changed since.': 'फ़ॉर्म के फ़ील्ड में टाइप करें, उसके बॉक्स टिक करें और उसकी सूचियों से चुनें। यहाँ रखे हस्ताक्षर आपके हस्ताक्षर का चित्र हैं, डिजिटल हस्ताक्षर नहीं: ये सिद्ध नहीं करते कि किसने हस्ताक्षर किए, या कि उसके बाद PDF नहीं बदला।',
