  '{provider} refused the password: it wants an app password, made in the account\'s security settings.': '{provider} ने पासवर्ड अस्वीकार कर दिया: इसे ऐप पासवर्ड चाहिए, जो खाते की सुरक्षा सेटिंग में बनता है।',
