  'Marks: the Comments pane, where each mark can be found and deleted': 'चिह्न: टिप्पणियाँ फलक, जहाँ हर चिह्न खोजा और हटाया जा सकता है',
  'Markup': 'मार्कअप',
  'Mask': 'मास्क',
