  'Perspective': 'परिप्रेक्ष्य',
  'Perspective: a corner and its neighbour move apart, as if seen at an angle': 'परिप्रेक्ष्य: एक कोना और उसका पड़ोसी अलग होते हैं, जैसे किसी कोण से देखा गया हो',
  'Perspective: set four pins on something that should be square, and straighten it': 'परिप्रेक्ष्य: किसी ऐसी चीज़ पर चार पिन लगाएँ जो सीधी होनी चाहिए, और उसे सीधा करें',
