  'Scale: a corner grows or shrinks the picture from the opposite corner; Shift keeps its shape': 'स्केल: कोना चित्र को सामने वाले कोने से बड़ा या छोटा करता है; Shift उसका आकार बनाए रखता है',
  'Second colour': 'दूसरा रंग',
