  'Swap the colours': 'रंग अदला-बदली करें',
  'Swap the colours (X)': 'रंग अदला-बदली करें (X)',
  'The Adjust and Filters tabs change this layer while its selection stays.': 'जब तक इसका चयन बना है, समायोजन और फ़िल्टर टैब इस परत को बदलते हैं।',
  'The layer is locked. Unlock it to paint on it.': 'परत लॉक है। उस पर रंगने के लिए लॉक खोलें।',
  'The layer\'s mask: white shows, black hides. Click to paint on it.': 'परत का मास्क: सफ़ेद दिखाता है, काला छिपाता है। उस पर रंगने के लिए क्लिक करें।',
  'The pictures were already small enough. The copy is saved as {name}.': 'चित्र पहले से काफ़ी छोटे थे। प्रति {name} के रूप में सहेजी गई।',
  'The pins cross. Put them on four corners, in order round the shape.': 'पिन एक-दूसरे को काट रहे हैं। उन्हें आकृति के चारों ओर क्रम से चार कोनों पर रखें।',
  'There is a selection: these change only what is selected, on a layer of its own. Deselect (Ctrl+D) to change the whole picture.': 'एक चयन है: ये केवल चुने हुए हिस्से को बदलते हैं, अपनी अलग परत पर। पूरे चित्र को बदलने के लिए चयन हटाएँ (Ctrl+D)।',
