  'Open a PDF': 'PDF खोलें',
  'Open a PDF to read it, or to rotate, move, delete, extract and insert pages. Merge Files combines several into one. Your file is changed only when you save over it.': 'PDF खोलें उसे पढ़ने के लिए, या पृष्ठ घुमाने, खिसकाने, हटाने, निकालने और सम्मिलित करने के लिए। फ़ाइलें मिलाएँ कई फ़ाइलों को एक में जोड़ता है। आपकी फ़ाइल तभी बदलती है जब आप उस पर सहेजते हैं।',
  'Open in PDF': 'PDF में खोलें',
  'Open in PDF: this PDF in the PDF app, to rotate, move, extract and insert its pages': 'PDF में खोलें: यह PDF, PDF ऐप में, इसके पृष्ठ घुमाने, खिसकाने, निकालने और सम्मिलित करने के लिए',
  'Open: a PDF in this window, or in a new one when this one has a document (Ctrl+O)': 'खोलें: PDF इस विंडो में, या नई विंडो में जब इसमें दस्तावेज़ खुला हो (Ctrl+O)',
