  'Reading…': 'पढ़ा जा रहा है…',
  'Recovered PDF': 'पुनर्प्राप्त PDF',
  'Replace the Original': 'मूल फ़ाइल बदलें',
  'Replace {name}?': '{name} को बदलें?',
  'Rotate Left: the selected pages a quarter turn anticlockwise (Ctrl+L)': 'बाएँ घुमाएँ: चुने गए पृष्ठ घड़ी की उलटी दिशा में चौथाई चक्कर (Ctrl+L)',
  'Rotate Right: the selected pages a quarter turn clockwise (Ctrl+R)': 'दाएँ घुमाएँ: चुने गए पृष्ठ घड़ी की दिशा में चौथाई चक्कर (Ctrl+R)',
  'Save As: the pages as a new PDF (Ctrl+Shift+S)': 'इस रूप में सहेजें: पृष्ठ एक नई PDF के रूप में (Ctrl+Shift+S)',
  'Save a Copy…': 'एक प्रति सहेजें…',
  'Save: the pages as they are now; the original is replaced only after you say so (Ctrl+S)': 'सहेजें: पृष्ठ जैसे अब हैं; मूल फ़ाइल आपके कहने के बाद ही बदली जाती है (Ctrl+S)',
  'Saving writes the pages as they are now over the original file. Save a Copy keeps the original as it is.': 'सहेजने से पृष्ठ जैसे अब हैं मूल फ़ाइल पर लिख दिए जाते हैं। एक प्रति सहेजें मूल को जैसा है वैसा रखता है।',
  'Single Page': 'एक पृष्ठ',
  'Single Page: one page at a time (Page Up and Page Down)': 'एक पृष्ठ: एक बार में एक पृष्ठ (Page Up और Page Down)',
  'Split and Merge': 'विभाजन और मिलान',
  'Split into {count} file in {folder}': { one: '{folder} में {count} फ़ाइल में विभाजित', other: '{folder} में {count} फ़ाइलों में विभाजित' },
  'Split: this PDF into several files, by a number of pages or at the selected pages': 'विभाजित करें: यह PDF कई फ़ाइलों में, पृष्ठों की संख्या से या चुने गए पृष्ठों पर',
  'The PDF could not be saved: {reason}': 'PDF सहेजी नहीं जा सकी: {reason}',
  'The PDF could not be split: {reason}': 'PDF विभाजित नहीं हो सकी: {reason}',
  'The page this bookmark goes to is not in the document now': 'जिस पृष्ठ पर यह बुकमार्क जाता है वह अब दस्तावेज़ में नहीं',
  'The page this link goes to is not in the document now.': 'जिस पृष्ठ पर यह लिंक जाता है वह अब दस्तावेज़ में नहीं।',
  'The pages could not be exported: {reason}': 'पृष्ठ निर्यात नहीं किए जा सके: {reason}',
  'The pages could not be extracted: {reason}': 'पृष्ठ निकाले नहीं जा सके: {reason}',
  'The pages could not be printed: {reason}': 'पृष्ठ प्रिंट नहीं हो सके: {reason}',
  'This PDF is protected': 'यह PDF सुरक्षित है',
  'This PDF is protected, so its pages can be read but not changed or saved yet.': 'यह PDF सुरक्षित है, इसलिए इसके पृष्ठ पढ़े जा सकते हैं पर अभी बदले या सहेजे नहीं जा सकते।',
  'This makes {count} file, in a folder you choose. This document is not changed.': { one: 'इससे {count} फ़ाइल बनती है, आपके चुने फ़ोल्डर में। यह दस्तावेज़ नहीं बदलता।', other: 'इससे {count} फ़ाइलें बनती हैं, आपके चुने फ़ोल्डर में। यह दस्तावेज़ नहीं बदलता।' },
