  "Quick Parts: words you keep to put in again, AutoText, a field: a page number, the date, the file's name": 'त्वरित भाग: दोबारा सम्मिलित करने के लिए सहेजे गए शब्द, स्वतः टेक्स्ट, कोई फ़ील्ड: पृष्ठ संख्या, दिनांक, फ़ाइल का नाम',
