  'From Picture: a table in a picture read into cells, or a receipt or an invoice into a row, on this computer and checked in a preview before it goes in': 'चित्र से: चित्र की तालिका कक्षों में, या रसीद या बीजक एक पंक्ति में, इसी कंप्यूटर पर पढ़ा जाता है और डालने से पहले पूर्वावलोकन में जाँचा जाता है',
