  'Make Check Box Fields: the tick boxes become check boxes of the form, ticked as they were read, to fill and save': 'चेक बॉक्स फ़ील्ड बनाएँ: टिक बॉक्स फ़ॉर्म के चेक बॉक्स बन जाते हैं, जैसे पढ़े गए वैसे ही टिक किए, भरने और सहेजने के लिए',
  'No fields were found. Recognise Text with Find fields ticked reads an invoice\'s or a receipt\'s fields and a form\'s tick boxes.': 'कोई फ़ील्ड नहीं मिली। फ़ील्ड खोजें टिक करके पाठ पहचान बीजक या रसीद की फ़ील्ड और फ़ॉर्म के टिक बॉक्स पढ़ती है।',
  'Text recognised, and fields found on {count} page: they are in the Fields pane.': { one: 'पाठ पहचाना गया, और {count} पृष्ठ पर फ़ील्ड मिलीं: वे फ़ील्ड फलक में हैं।', other: 'पाठ पहचाना गया, और {count} पृष्ठों पर फ़ील्ड मिलीं: वे फ़ील्ड फलक में हैं।' },
